(6979422, 1053555, 16148, '<td valign="top">All the elements of a nice image but the processing isn''t working for me.  Everything seems to dark except for the kids.</td>', 'All the elements of a nice image but the processing isn''t working for me.  Everything seems to dark except for the kids.', '2013-02-14 17:43:13.000000', NULL, 1),
(6979423, 1053515, 16148, '<td valign="top">Nice textures in the tree and stone wall but, in my opinion, you need more contrast.</td>', 'Nice textures in the tree and stone wall but, in my opinion, you need more contrast.', '2013-02-14 17:47:36.000000', NULL, 1),
(6979425, 1053388, 16148, '<td valign="top">Maybe to much sharpening.  You can see mottling in the sky that detracts.</td>', 'Maybe to much sharpening.  You can see mottling in the sky that detracts.', '2013-02-14 17:50:03.000000', NULL, 1),
(6979436, 1053454, 158576, '<td valign="top">The image lacks the range of shadows and highlights one expects in Jagar''s style. The tones seem so similar that it seems flat and nothing really stands out.</td>', 'The image lacks the range of shadows and highlights one expects in Jagar''s style. The tones seem so similar that it seems flat and nothing really stands out.', '2013-02-14 18:35:12.000000', NULL, 1),
(6979437, 1053356, 158576, '<td valign="top">A touching image of someone that seems isolated and alone. He looks uncertain and apprehensive. Great capture!</td>', 'A touching image of someone that seems isolated and alone. He looks uncertain and apprehensive. Great capture!', '2013-02-14 18:37:27.000000', NULL, 1),
(6979442, 1053224, 158576, '<td valign="top">The shadows are so dark and the midtones are so similar it feels flat and lacking dimension.</td>', 'The shadows are so dark and the midtones are so similar it feels flat and lacking dimension.', '2013-02-14 18:50:04.000000', NULL, 1),
(6979444, 1053240, 158576, '<td valign="top">Photos of shoes on wires are very cliche and there''s nothing that sets this apart.</td>', 'Photos of shoes on wires are very cliche and there''s nothing that sets this apart.', '2013-02-14 18:53:38.000000', NULL, 1),
(6979445, 1053554, 158576, '<td valign="top">I can feel the story in this photo. Nice work.</td>', 'I can feel the story in this photo. Nice work.', '2013-02-14 18:55:20.000000', NULL, 1),
(6979446, 1053494, 158576, '<td valign="top">Stunning. Great lighting, great setting, you can feel the romance! Would make a great book cover!</td>', 'Stunning. Great lighting, great setting, you can feel the romance! Would make a great book cover!', '2013-02-14 18:58:48.000000', NULL, 1),
(6979449, 1053452, 158576, '<td valign="top">Nice portrait. I like the sparkle in his eyes.</td>', 'Nice portrait. I like the sparkle in his eyes.', '2013-02-14 19:10:37.000000', NULL, 1),
(6979451, 1053150, 158576, '<td valign="top">Photos that tell a story always make me take a second look. I actually took 4 looks at this one. The setting is interesting, the highlights and shadows really give the photo dimension, but the expression on his face it what catches my attention.</td>', 'Photos that tell a story always make me take a second look. I actually took 4 looks at this one. The setting is interesting, the highlights and shadows really give the photo dimension, but the expression on his face it what catches my attention.', '2013-02-14 19:15:17.000000', NULL, 1),
(6979453, 1053455, 158576, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2013-02-14 19:19:40.000000', NULL, 1),
(6979454, 1053524, 158576, '<td valign="top">Beautiful lighting and a face with great character.</td>', 'Beautiful lighting and a face with great character.', '2013-02-14 19:22:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6979455, 1053273, 158576, '<td valign="top">A shot that would not be out of place in National Geographic. Great photo journalism!</td>', 'A shot that would not be out of place in National Geographic. Great photo journalism!', '2013-02-14 19:23:59.000000', NULL, 1),
(6979456, 1053432, 158576, '<td valign="top">You captured an interesting moment. I can''t help but wonder what she''s thinking as she looks into the window. Is she reliving a memory or wondering what might have been...</td>', 'You captured an interesting moment. I can''t help but wonder what she''s thinking as she looks into the window. Is she reliving a memory or wondering what might have been...', '2013-02-14 19:27:26.000000', NULL, 1),
