(6980302, 1053501, 108580, '<td valign="top">The essence of Jagar. Exceptionally well spotted and shot with human subject in view. Good PP to match genre.</td>', 'The essence of Jagar. Exceptionally well spotted and shot with human subject in view. Good PP to match genre.', '2013-02-16 15:21:10.000000', NULL, 1),
(6980381, 1053540, 108069, '<td valign="top">Lovely light, contrast, detail, tones... the whole package. Beautiful entry.</td>', 'Lovely light, contrast, detail, tones... the whole package. Beautiful entry.', '2013-02-16 19:46:23.000000', NULL, 1),
(6980625, 1053548, 41337, '<td valign="top">Nice image. The lighting is soft, which is good. However the photo is lacking something. It needs <i>some</i> context in which curiosity is to spring from. In my opinion this would be better suited shot at a restaurant or some place with the background intact. It would give the photo authenticity and with it invite others of a more curious nature into the world you show us. If there''s one takeaway from jagar''s style it''s that.</td>', 'Nice image. The lighting is soft, which is good. However the photo is lacking something. It needs some context in which curiosity is to spring from. In my opinion this would be better suited shot at a restaurant or some place with the background intact. It would give the photo authenticity and with it invite others of a more curious nature into the world you show us. If there''s one takeaway from jagar''s style it''s that.', '2013-02-17 13:19:44.000000', NULL, 1),
(6980628, 1053546, 41337, '<td valign="top">I''m not sure how this fits. If you''re going to buck the trend maybe be more daring in scope and execution? Just a suggestion.</td>', 'I''m not sure how this fits. If you''re going to buck the trend maybe be more daring in scope and execution? Just a suggestion.', '2013-02-17 13:27:55.000000', NULL, 1),
(6980629, 1053292, 41337, '<td valign="top">Being blunt with your titles robs your photo of whatever it has to say. Why do that?</td>', 'Being blunt with your titles robs your photo of whatever it has to say. Why do that?', '2013-02-17 13:32:24.000000', NULL, 1),
(6980631, 1053133, 41337, '<td valign="top">Did you take this from your car?</td>', 'Did you take this from your car?', '2013-02-17 13:41:57.000000', NULL, 1),
