(6981177, 1053483, 63218, '<td valign="top">haha, thanks for the humor!</td>', 'haha, thanks for the humor!', '2013-02-18 13:46:50.000000', NULL, 1),
(6981237, 1053540, 143116, '<td valign="top">I think this is the true jagar. If not, it certainly is one of the best images in this challenge.</td>', 'I think this is the true jagar. If not, it certainly is one of the best images in this challenge.', '2013-02-18 15:59:36.000000', NULL, 1),
