(6981286, 1053426, 143116, '<td valign="top">Top 3 shot for me!</td>', 'Top 3 shot for me!', '2013-02-18 17:14:57.000000', NULL, 1),
(6981289, 1053544, 62357, '<td valign="top">Voted already.  This is truly my favourite in the whole challenge. It''s the late - just perfect.</td>', 'Voted already.  This is truly my favourite in the whole challenge. It''s the late - just perfect.', '2013-02-18 17:25:00.000000', NULL, 1),
(6981306, 1053150, 63218, '<td valign="top">seemingly lacking in content nevertheless strangely interesting to look at. must be the light.</td>', 'seemingly lacking in content nevertheless strangely interesting to look at. must be the light.', '2013-02-18 18:15:40.000000', NULL, 1),
