(6981343, 1053111, 73828, '<td valign="top">Great Picture! Congratulations!</td>', 'Great Picture! Congratulations!', '2013-02-18 20:15:04.000000', NULL, 1),
(6981344, 1053494, 73828, '<td valign="top">Great! I love the late night romantic tone. Congratulations!</td>', 'Great! I love the late night romantic tone. Congratulations!', '2013-02-18 20:16:58.000000', NULL, 1),
(6981378, 1053240, 152252, '<td valign="top">Nice composition, and an interesting image</td>', 'Nice composition, and an interesting image', '2013-02-18 21:33:05.000000', NULL, 1),
(6981379, 1053543, 15574, '<td valign="top">Great capture. The thing I love about Jagar''s pictures is that there are little things that others might find undesirable (stop sign covering face.) I think that''s what makes his shots unique.</td>', 'Great capture. The thing I love about Jagar''s pictures is that there are little things that others might find undesirable (stop sign covering face.) I think that''s what makes his shots unique.', '2013-02-18 21:35:36.000000', NULL, 1),
(6981380, 1052859, 152252, '<td valign="top">I really love the silhouettes and the arch. Great image.</td>', 'I really love the silhouettes and the arch. Great image.', '2013-02-18 21:36:10.000000', NULL, 1),
(6981381, 1053501, 152252, '<td valign="top">Great find!</td>', 'Great find!', '2013-02-18 21:36:58.000000', NULL, 1),
(6981382, 1053388, 15574, '<td valign="top">Looks nuked from over-sharpening. You can tell something''s up by the specs all in the sky.</td>', 'Looks nuked from over-sharpening. You can tell something''s up by the specs all in the sky.', '2013-02-18 21:37:21.000000', NULL, 1),
(6981383, 1053497, 15574, '<td valign="top">Great portrait. B&amp;W processing is spot on.</td>', 'Great portrait. B&W processing is spot on.', '2013-02-18 21:37:54.000000', NULL, 1),
(6981384, 1053432, 15574, '<td valign="top">Love the subject matter. That''s a great capture. I wish somehow her face was shown though, even just a little.</td>', 'Love the subject matter. That''s a great capture. I wish somehow her face was shown though, even just a little.', '2013-02-18 21:39:20.000000', NULL, 1),
(6981385, 1053528, 152252, '<td valign="top">Great light that helped showing the wrinkles. Love the light in the eyes. Amazing model. Wish the nose was sharper. But overall I love this portrait!</td>', 'Great light that helped showing the wrinkles. Love the light in the eyes. Amazing model. Wish the nose was sharper. But overall I love this portrait!', '2013-02-18 21:39:30.000000', NULL, 1),
(6981386, 1053111, 152252, '<td valign="top">Magic! Love the atmosphere of this photo</td>', 'Magic! Love the atmosphere of this photo', '2013-02-18 21:42:40.000000', NULL, 1),
(6981387, 1053442, 15574, '<td valign="top">The thing I love about Jagar''s shots is the absolute candid nature of them. They have a rawness and they aren''t "technically" perfect. That''s what I enjoy about them. If I had to guess out of all the entries, I''d say this is the man himself.</td>', 'The thing I love about Jagar''s shots is the absolute candid nature of them. They have a rawness and they aren''t "technically" perfect. That''s what I enjoy about them. If I had to guess out of all the entries, I''d say this is the man himself.', '2013-02-18 21:46:26.000000', NULL, 1),
(6981388, 1053467, 15574, '<td valign="top">The light and shadows work really well here. And great capture with the bird. There''s something about the crop though, it feels a little too tight.</td>', 'The light and shadows work really well here. And great capture with the bird. There''s something about the crop though, it feels a little too tight.', '2013-02-18 21:47:58.000000', NULL, 1),
(6981389, 1053391, 15574, '<td valign="top">The b&amp;w works great here and doesn''t look forced. Almost looks like film with the gray hues.</td>', 'The b&w works great here and doesn''t look forced. Almost looks like film with the gray hues.', '2013-02-18 21:49:34.000000', NULL, 1),
(6981390, 1053007, 152252, '<td valign="top">Ernie is an interesting model. Nice portrait!</td>', 'Ernie is an interesting model. Nice portrait!', '2013-02-18 21:50:19.000000', NULL, 1),
(6981391, 1053523, 152252, '<td valign="top">The expression on her face is priceless... Very well "caught" and nicely composed!</td>', 'The expression on her face is priceless... Very well "caught" and nicely composed!', '2013-02-18 21:51:29.000000', NULL, 1),
(6981392, 1053524, 15574, '<td valign="top">Now this is a fantastic portrait. B&amp;w, bokeh, and clarity are about as good as they can get.</td>', 'Now this is a fantastic portrait. B&w, bokeh, and clarity are about as good as they can get.', '2013-02-18 21:51:47.000000', NULL, 1),
(6981393, 1053455, 152252, '<td valign="top">One of my two guesses for Jagar''s photo. Very well done!</td>', 'One of my two guesses for Jagar''s photo. Very well done!', '2013-02-18 21:52:50.000000', NULL, 1),
(6981394, 1053099, 15574, '<td valign="top">Awesome candid. There''s just something interesting about the old man browsing the market by himself. One of my favorites in the challenge.</td>', 'Awesome candid. There''s just something interesting about the old man browsing the market by himself. One of my favorites in the challenge.', '2013-02-18 21:53:12.000000', NULL, 1),
(6981395, 1053552, 15574, '<td valign="top">Interesting shot.I''m just having trouble finding the focal point. Maybe a wider angle would have helped. If you were going for abstract good job then.</td>', 'Interesting shot.I''m just having trouble finding the focal point. Maybe a wider angle would have helped. If you were going for abstract good job then.', '2013-02-18 21:55:30.000000', NULL, 1),
(6981397, 1053499, 152252, '<td valign="top">Lovely picture. Looks so European. I wanna back to Europe now :) Great job!</td>', 'Lovely picture. Looks so European. I wanna back to Europe now :) Great job!', '2013-02-18 21:56:38.000000', NULL, 1),
(6981398, 1053200, 15574, '<td valign="top">Nice capture. The processing feels a little bland though, esp for Jagar''s style.</td>', 'Nice capture. The processing feels a little bland though, esp for Jagar''s style.', '2013-02-18 21:57:36.000000', NULL, 1),
(6981399, 1053497, 152252, '<td valign="top">Nice light. His wrinkles and eyes look great.</td>', 'Nice light. His wrinkles and eyes look great.', '2013-02-18 21:57:50.000000', NULL, 1),
(6981400, 1053049, 15574, '<td valign="top">Love the negative space of the water. The b&amp;w works really well with this.</td>', 'Love the negative space of the water. The b&w works really well with this.', '2013-02-18 21:58:25.000000', NULL, 1),
(6981401, 1053426, 15574, '<td valign="top">Very nice lighting on the stones and the shadows are great. Not sure how I feel about the border though.</td>', 'Very nice lighting on the stones and the shadows are great. Not sure how I feel about the border though.', '2013-02-18 21:59:37.000000', NULL, 1),
(6981403, 1053260, 15574, '<td valign="top">Wow you don''t see that everyday. Awesome find. I love the solemn look on his face, def adds to the mood. I would have suggested pushing the blacks and contrast just a tad.</td>', 'Wow you don''t see that everyday. Awesome find. I love the solemn look on his face, def adds to the mood. I would have suggested pushing the blacks and contrast just a tad.', '2013-02-18 22:01:30.000000', NULL, 1),
(6981405, 1053455, 15574, '<td valign="top">This is a great candid street shot. VERY much in the style of Jagar. I love the way the stones of the sidewalk look with the shadows and highlights. Almost like a flowing stream as they warp.</td>', 'This is a great candid street shot. VERY much in the style of Jagar. I love the way the stones of the sidewalk look with the shadows and highlights. Almost like a flowing stream as they warp.', '2013-02-18 22:03:34.000000', NULL, 1),
(6981406, 1053491, 15574, '<td valign="top">Interesting capture. A little heavy on the contrast and blacks though.</td>', 'Interesting capture. A little heavy on the contrast and blacks though.', '2013-02-18 22:04:31.000000', NULL, 1),
(6981408, 1053201, 15574, '<td valign="top">Nice brown attempt. I think you might have this one!!</td>', 'Nice brown attempt. I think you might have this one!!', '2013-02-18 22:05:22.000000', NULL, 1),
(6981409, 1053546, 15574, '<td valign="top">I know Jagar doesn''t always shoot the candid street shots in b&amp;w....but really?</td>', 'I know Jagar doesn''t always shoot the candid street shots in b&w....but really?', '2013-02-18 22:06:12.000000', NULL, 1),
(6981411, 1053554, 15574, '<td valign="top">This is cute, poor girl. Looks like it''s a little out of focus and the b&amp;w is bland.</td>', 'This is cute, poor girl. Looks like it''s a little out of focus and the b&w is bland.', '2013-02-18 22:07:16.000000', NULL, 1),
(6981412, 1053392, 15574, '<td valign="top">Can''t say I see this everyday. I think a wider view would have done this better, it seems confined. To me at least.</td>', 'Can''t say I see this everyday. I think a wider view would have done this better, it seems confined. To me at least.', '2013-02-18 22:08:05.000000', NULL, 1),
(6981414, 1053454, 15574, '<td valign="top">I''d eat some. I think the processing really takes away from the main subject so it all feels cluttered.</td>', 'I''d eat some. I think the processing really takes away from the main subject so it all feels cluttered.', '2013-02-18 22:09:56.000000', NULL, 1),
(6981416, 1052963, 15574, '<td valign="top">The clarity and tone on this is stunning. I love the conversion,I''d be interested to see the color version.</td>', 'The clarity and tone on this is stunning. I love the conversion,I''d be interested to see the color version.', '2013-02-18 22:11:22.000000', NULL, 1),
(6981417, 1053039, 15574, '<td valign="top">I love this vantage point. With the left side taking up more of the picture I wish the couple was a little lighter to keep my eyes from shifting towards the left so much.</td>', 'I love this vantage point. With the left side taking up more of the picture I wish the couple was a little lighter to keep my eyes from shifting towards the left so much.', '2013-02-18 22:13:18.000000', NULL, 1),
