INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6982602, 1053442, 24454, '<td valign="top">Yep... certainly a 10 for me!  Amazing how many people knew this was you.  What a tribute!</td>', 'Yep... certainly a 10 for me!  Amazing how many people knew this was you.  What a tribute!', '2013-02-20 17:49:45.000000', NULL, 0),
(6982606, 1053367, 15574, '<td valign="top">This should have done much better. I have a feeling some voters didn''t take the time to fully take in the picture and see everything. I think the focus on the two in the window combined with the textures and  the lack of focus on the  pronounced foreground is great. Didn''t vote in this challenge but would have got an 8 from me.<br/><br/><i>Message edited by author 2013-02-20 17:54:45.</i></td>', 'This should have done much better. I have a feeling some voters didn''t take the time to fully take in the picture and see everything. I think the focus on the two in the window combined with the textures and  the lack of focus on the  pronounced foreground is great. Didn''t vote in this challenge but would have got an 8 from me.', '2013-02-20 17:53:13.000000', '2013-02-20 17:54:45.000000', 0),
(6982611, 1053240, 158518, '<td valign="top">thanks to all for comments and votes<br/> <br/>this is not a good placement, but there was so many photos of very high level!<br/> <br/>it was a good way to brake the ice anyway ;)</td>', 'thanks to all for comments and votes this is not a good placement, but there was so many photos of very high level! it was a good way to brake the ice anyway ;)', '2013-02-20 18:19:46.000000', NULL, 0),
